steps.data:
/**
 * ILANEL POC — Ross Gardam clone
 *
 * Values taken from rossgardam.com.au's live stylesheet, not estimated:
 *   .article__content p  font-size 1.8rem / weight 300 / line-height 1.35
 *   .article__head       margin-bottom 4.1rem
 *   .section-details     padding 0 0 18rem
 *   letter-spacing       .005 / .01 / .02 / .06 / .08em
 *   body                 #fff bg, #000 text, ABCFavorit
 *   font-weights         300 / 400 / 600 only
 *
 * RG use ABCFavorit (grotesque) + Lyon Display (serif wordmark and
 * product names). Both are licensed and cannot be redistributed, so this
 * substitutes Inter and a Didone serif. Swap in the licensed faces for
 * production and the match tightens further.
 *
 * 1rem = 10px here, as on RG. They declare `html{font-size:10px}` rather
 * than the 62.5% idiom — same computed result, so their rem values transfer
 * directly. (An earlier comment here claimed 62.5%; that was never in their
 * stylesheet. Verified against their served CSS 2026-08-12.)
 *
 * KNOWN DIVERGENCES from RG, measured against their live CSS — deliberate or
 * not yet addressed, but do not "fix" them assuming they are typos:
 *
 *   .shell        RG 183.5rem max-width, 10rem side padding (5rem ≤1199,
 *                 6rem ≤1023, 3rem mobile). Ours: 168rem / 3rem. Ours is a
 *                 narrower, tighter page.
 *   sections      RG's vertical rhythm is much larger than ours: 16.7rem
 *                 top / 14.7rem bottom on desktop, collapsing to 10rem then
 *                 5rem. Ours run ~4-7rem. This is the single biggest reason
 *                 our page reads denser than theirs.
 *   h2            RG 2.8rem/400/1.15 (2.6 ≤1023, 2.4 mobile) in the sans.
 *                 Ours are serif and much larger — a deliberate departure,
 *                 since our headings carry the page where RG lean on imagery.
 *   h2 margin     RG .section h2 { margin-bottom: 9.8rem } — nearly 100px of
 *                 air under every section heading.
 *   "Latest       RG is NOT a product grid. It is a one-slide-at-a-time
 *    Releases"    Flickity carousel, slide width 100%, image ratio via
 *                 padding-top 55.4% (80% mobile), with the caption OVERLAID
 *                 bottom-right on the image (position absolute, max-width
 *                 58rem, padding 4.7rem 6.3rem, opacity .8) — not beneath it.
 *                 Ours is a 4-up card grid. Different component by choice.
 *   hover         RG have no image zoom on the homepage. Their motion is a
 *                 1px underline scaleX(0) -> none over .4s ease. Ours scales
 *                 the product image 1.03.
 */

html {
  font-size: 10px;
}

/* --- Page transitions -----------------------------------------------------
 * The page starts faded and lifts in; on leaving it fades back out before
 * navigation. Softens the hard cut between pages without a SPA router.
 *
 * `.is-ready` is added by transitions.js. The `no-js` guard means the page
 * is fully visible when JavaScript is unavailable — never a blank page.
 */

html.is-transitions body {
  opacity: 0;
  transform: translateY(0.8rem);
}

html.is-transitions.is-ready body {
  opacity: 1;
  transform: none;
  transition: opacity 0.42s ease, transform 0.42s cubic-bezier(0.16, 1, 0.3, 1);
}

html.is-transitions.is-leaving body {
  opacity: 0;
  transform: translateY(-0.5rem);
  transition: opacity 0.3s ease, transform 0.3s ease;
}

@media (prefers-reduced-motion: reduce) {
  html.is-transitions body,
  html.is-transitions.is-ready body,
  html.is-transitions.is-leaving body {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

:root {
  --rg-ink: #000;
  --rg-bg: #fff;
  --rg-tile: #eee;
  --rg-tile-alt: #f4f4f4;
  --rg-rule: #d5d5d5;
  --rg-muted: #767676;
  --rg-accent: #8a6d3b;

  --rg-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
  --rg-serif: 'Playfair Display', 'Times New Roman', serif;

  --rg-shell: 3rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Any rule that sets `display` beats the browser default for [hidden], so
   state it explicitly — otherwise elements toggled via the hidden attribute
   stay visible. */
[hidden] {
  display: none !important;
}

body {
  margin: 0;
  background: var(--rg-bg);
  color: var(--rg-ink);
  font-family: var(--rg-sans);
  font-weight: 400;
  font-size: 1.5rem;
  line-height: 1.5;
  text-align: left;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.rg-shell {
  max-width: 168rem;
  margin: 0 auto;
  padding: 0 var(--rg-shell);
}

/* --- Header --------------------------------------------------------------- */

.rg-header {
  padding: 3.2rem 0 2.8rem;
}

.rg-header__inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 0 var(--rg-shell);
}

.rg-navbtn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5rem;
  width: 2.4rem;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

.rg-navbtn span {
  display: block;
  height: 1px;
  background: var(--rg-ink);
}

.rg-navbtn span:nth-child(2) {
  width: 70%;
}

.rg-header__logo {
  grid-column: 2;
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 2.9rem;
  font-weight: 400;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1;
  text-indent: 0.18em;
}

.rg-utilities {
  grid-column: 3;
  display: flex;
  justify-content: flex-end;
  gap: 1.8rem;
}

/* --- Hero ----------------------------------------------------------------- */

/* --- Hero carousel -------------------------------------------------------- */

/* On product pages the header sits over the hero, so the image runs to the
   very top of the page — including behind the wordmark. */
body.has-hero .rg-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  color: #fff;
}

body.has-hero .rg-navbtn span {
  background: #fff;
}

/* A soft scrim keeps the white header legible over pale photography. */
body.has-hero .rg-header::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0));
  pointer-events: none;
  z-index: -1;
}

/* Sized in vh so it fills the top of the viewport without swallowing the
   page. Capped so tall desktop windows don't stretch it absurdly. */
.rg-hero {
  position: relative;
  width: 100%;
  height: 82vh;
  max-height: 84rem;
  min-height: 48rem;
  background-color: var(--rg-tile);
  overflow: hidden;
}

.rg-hero__slide {
  position: absolute;
  inset: 0;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  opacity: 0;
  transition: opacity 1.1s ease;
}

.rg-hero__slide.is-active {
  opacity: 1;
}

.rg-hero__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 3;
  width: 5rem;
  height: 5rem;
  border: 0;
  background: none;
  color: #fff;
  font-size: 3.2rem;
  line-height: 1;
  cursor: pointer;
  opacity: 0.75;
  transition: opacity 0.2s ease;
}

.rg-hero__nav:hover {
  opacity: 1;
}

.rg-hero__nav--prev {
  left: 1rem;
}

.rg-hero__nav--next {
  right: 1rem;
}

.rg-hero__dots {
  position: absolute;
  bottom: 3rem;
  left: 0;
  right: 0;
  z-index: 3;
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.rg-hero__dot {
  width: 4rem;
  height: 2px;
  padding: 0;
  border: 0;
  background: rgba(255, 255, 255, 0.45);
  cursor: pointer;
  transition: background 0.25s ease;
}

.rg-hero__dot.is-active {
  background: #fff;
}

/* --- Breadcrumbs ---------------------------------------------------------- */

.rg-breadcrumbs {
  padding: 2.6rem 0;
}

.rg-breadcrumbs--inline {
  padding: 0 0 3.5rem;
}

.ilanel-breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.ilanel-breadcrumbs li + li::before {
  content: '/';
  margin-right: 0.9rem;
}

.ilanel-breadcrumbs a:hover {
  color: var(--rg-ink);
}

.ilanel-breadcrumbs [aria-current='page'] {
  color: var(--rg-ink);
}

/* --- Product article ------------------------------------------------------ */

.rg-main {
  padding-bottom: 2rem;
}

/* .rg-article shares an element with .rg-shell, so it must not reset the
   horizontal padding — doing so clipped the product name off the page. */
.rg-article {
  padding-top: 4.5rem;
  padding-bottom: 4.5rem;
}

.rg-article__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
  gap: 8rem;
  align-items: start;
}

.rg-article__head {
  margin-bottom: 2.5rem;
}

/* The piece name: large, light serif — RG's signature move. */
.rg-product__name {
  margin: 0 0 1rem;
  font-family: var(--rg-serif);
  font-size: 5.6rem;
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: 0.01em;
}

.rg-product__type {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-article__content p {
  max-width: 60rem;
  margin: 0 0 2.2rem;
  font-size: 1.8rem;
  font-weight: 300;
  line-height: 1.35;
}

.rg-meta {
  display: flex;
  gap: 1.5rem;
  margin: 0 0 0.7rem;
  font-size: 1.3rem;
  font-weight: 300;
}

.rg-meta__label {
  min-width: 9rem;
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

/* RG's link style: uppercase, tracked, trailing slash, underline on hover. */
.rg-cta {
  margin: 3.5rem 0 0;
}

.rg-link {
  display: inline-block;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-link:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Storytelling --------------------------------------------------------- */

.rg-story {
  padding: 1rem 0 2rem;
}

.rg-article__row--middle {
  align-items: center;
}

/* RG alternate the media side; --reversed puts copy first. */
.rg-article--reversed .rg-article__row {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
}

.rg-feature img {
  width: 100%;
  background: var(--rg-tile);
}

/* ILANEL's scene photography is wide; a 4:5 portrait crop cut the fixture
   out of frame entirely. 5:4 keeps the piece visible. */
.rg-feature--portrait img {
  aspect-ratio: 5 / 4;
  object-fit: cover;
}

.rg-feature--landscape img {
  aspect-ratio: 3 / 2;
  object-fit: cover;
}

.rg-story__title {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 3.2rem;
  font-weight: 400;
  line-height: 1.15;
}

/* --- Configurator --------------------------------------------------------- */

.rg-configure {
  padding: 6rem 0;
  background: var(--rg-tile-alt);
  margin-top: 2rem;
}

.rg-configure__inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 6rem;
  align-items: start;
}

.rg-configure__preview {
  background: #fff;
  aspect-ratio: 895 / 1023;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.rg-configure__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.3s ease;
}

.rg-configure__head {
  margin-bottom: 3rem;
}

.rg-configure__eyebrow {
  margin: 0 0 0.6rem;
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-configure__title {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 3.6rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-configure__title span {
  display: block;
  margin-top: 0.5rem;
  font-family: var(--rg-sans);
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__group {
  margin: 0 0 3rem;
  padding: 2rem 0 0;
  border: 0;
  border-top: 1px solid var(--rg-rule);
}

.rg-config__label {
  display: block;
  margin-bottom: 1.4rem;
  padding: 0;
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__options {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.rg-config__pill input,
.rg-config__swatch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.rg-config__pill span {
  display: inline-block;
  padding: 0.9rem 2rem;
  border: 1px solid var(--rg-rule);
  font-size: 1.2rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.rg-config__pill:hover span {
  border-color: var(--rg-ink);
}

.rg-config__pill input:checked + span {
  background: var(--rg-ink);
  border-color: var(--rg-ink);
  color: #fff;
}

/* --- Scale drawing --------------------------------------------------------
 * "1800 mm" is meaningless to most buyers. Drawn against a dining table
 * and a human figure, the right length becomes obvious — and wrong-size
 * orders are the most expensive mistake in made-to-order lighting.
 */

.rg-scale {
  margin-top: 2.5rem;
  padding: 2rem 2rem 1.5rem;
  background: #fff;
  border: 1px solid var(--rg-rule);
}

.rg-scale__stage {
  position: relative;
  height: 11rem;
}

/* The pendant, drawn to scale and animating between lengths. */
.rg-scale__fixture {
  position: absolute;
  top: 1.4rem;
  left: 50%;
  transform: translateX(-50%);
  height: 3px;
  background: linear-gradient(90deg, #c9a24a, #e4cd8f, #c9a24a);
  border-radius: 2px;
  transition: width 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-scale__fixture::before,
.rg-scale__fixture::after {
  content: '';
  position: absolute;
  top: -0.35rem;
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 50%;
  background: #dcb968;
  box-shadow: 0 0 0.8rem rgba(220, 185, 104, 0.8);
}

.rg-scale__fixture::before {
  left: -0.4rem;
}

.rg-scale__fixture::after {
  right: -0.4rem;
}

/* The reference table. */
.rg-scale__table {
  position: absolute;
  bottom: 2.2rem;
  left: 50%;
  transform: translateX(-50%);
  width: 78%;
  height: 0.6rem;
  background: #cfc3b0;
  border-radius: 1px;
}

.rg-scale__table::before,
.rg-scale__table::after {
  content: '';
  position: absolute;
  top: 0.6rem;
  width: 0.5rem;
  height: 2.2rem;
  background: #cfc3b0;
}

.rg-scale__table::before {
  left: 8%;
}

.rg-scale__table::after {
  right: 8%;
}

.rg-scale__tablelabel {
  position: absolute;
  top: -1.9rem;
  right: 0;
  font-size: 0.95rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #aaa;
}

/* A 1.7 m figure for human reference. */
.rg-scale__person {
  position: absolute;
  bottom: 2.2rem;
  left: 4%;
  width: 1.5rem;
  height: 6.4rem;
  border-radius: 0.75rem 0.75rem 0 0;
  background: #e2e2e2;
}

.rg-scale__person::before {
  content: '';
  position: absolute;
  top: -1.7rem;
  left: 50%;
  transform: translateX(-50%);
  width: 1.5rem;
  height: 1.5rem;
  border-radius: 50%;
  background: #e2e2e2;
}

.rg-scale__caption {
  margin: 0.5rem 0 0;
  font-size: 1.05rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--rg-muted);
  text-align: center;
}

.rg-scale__caption .js-scale-caption {
  color: var(--rg-ink);
}

/* --- Unavailable options --------------------------------------------------
 * An option that leads nowhere is dimmed and struck through *before* it is
 * clicked. Cheaper than letting someone pick it and then explaining why the
 * price vanished.
 */

.rg-config__pill.is-unavailable,
.rg-config__swatch.is-unavailable {
  opacity: 0.32;
  cursor: not-allowed;
}

.rg-config__pill.is-unavailable span {
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}

.rg-config__pill.is-unavailable:hover span {
  border-color: var(--rg-rule);
}

.rg-config__swatch.is-unavailable .rg-config__swatch-media {
  filter: grayscale(1);
}

.rg-config__unavailable {
  margin: 0 0 1.5rem;
  padding: 1rem 1.4rem;
  background: #fff;
  border-left: 2px solid var(--rg-accent);
  font-size: 1.2rem;
  font-weight: 300;
  color: #444;
}

/* The price is the number people are deciding on — give the change a beat. */
.js-config-price {
  display: inline-block;
  transition: opacity 0.2s ease;
  font-variant-numeric: tabular-nums;
}

.rg-config.is-unavailable .js-config-price {
  opacity: 0.35;
}

/* --- Restored-selection note ---------------------------------------------- */

.rg-config__restored {
  margin: 0 0 2rem;
  padding: 1rem 1.4rem;
  background: #fff;
  border-left: 2px solid var(--rg-accent);
  font-size: 1.2rem;
  font-weight: 300;
  color: #444;
}

.rg-config__options--swatches {
  gap: 1.6rem;
}

.rg-config__swatch {
  width: 8rem;
  cursor: pointer;
}

.rg-config__swatch-media {
  display: block;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  border: 1px solid transparent;
  outline: 1px solid var(--rg-rule);
  outline-offset: -1px;
  transition: outline-color 0.2s ease;
}

.rg-config__swatch-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rg-config__swatch input:checked + .rg-config__swatch-media {
  outline: 2px solid var(--rg-ink);
  outline-offset: 2px;
}

.rg-config__swatch-name {
  display: block;
  margin-top: 0.8rem;
  font-size: 1rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__summary {
  margin: 3rem 0;
  padding-top: 2rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-config__summary p {
  display: flex;
  gap: 1.5rem;
  align-items: baseline;
  margin: 0 0 0.8rem;
  font-size: 1.4rem;
  font-weight: 300;
}

.rg-config__summary .rg-config__label {
  min-width: 11rem;
  margin: 0;
}

.rg-config__price .js-config-price {
  font-size: 2rem;
  font-weight: 400;
}

/* Stacked, full-width — RG present the actions as a vertical list, and it
   reads as a clear priority order rather than three competing pills. */
.rg-config__actions {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2rem;
  max-width: 34rem;
}

.rg-config__actions .rg-btn {
  width: 100%;
  text-align: center;
}

.rg-btn {
  display: inline-block;
  padding: 1.3rem 3.4rem;
  border: 1px solid var(--rg-ink);
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}

.rg-btn:hover {
  background: var(--rg-ink);
  color: #fff;
}

.rg-btn--solid {
  background: var(--rg-ink);
  color: #fff;
}

.rg-btn--solid:hover {
  background: transparent;
  color: var(--rg-ink);
}

.rg-config__download {
  margin: 0;
}

/* --- Sections (Finishes, Downloads) --------------------------------------- */

.rg-section {
  padding: 4rem 0;
}

.rg-section--details {
  padding-bottom: 5rem;
}

.rg-section__label {
  display: block;
  margin-bottom: 2.5rem;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4rem 8rem;
  padding-top: 2.5rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-section__title {
  max-width: 38rem;
  margin: 0;
  font-size: 2.2rem;
  font-weight: 300;
  line-height: 1.3;
  letter-spacing: 0.005em;
}

.rg-section__list {
  margin: 0;
  padding: 0;
  list-style: none;
  columns: 2;
  column-gap: 4rem;
}

.rg-section__list li {
  margin-bottom: 1.4rem;
  font-size: 1.4rem;
  font-weight: 300;
  break-inside: avoid;
}

.rg-section__list--links li {
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-section__list--links a {
  border-bottom: 1px solid var(--rg-rule);
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-section__list--links a:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Range archive -------------------------------------------------------- */

.rg-main--archive {
  padding-top: 1rem;
}

.rg-range__header {
  margin-bottom: 4.5rem;
}

.rg-range__title {
  margin: 0 0 1.2rem;
  font-family: var(--rg-serif);
  font-size: 4.4rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-range__intro {
  max-width: 52rem;
}

.rg-range__intro p {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 300;
  line-height: 1.4;
  color: #333;
}

/* Filters: accent label, hairline rule, wide-spaced terms. */
.rg-filters {
  margin-bottom: 4.5rem;
}

.rg-filters__label {
  display: block;
  margin-bottom: 1.2rem;
  padding-bottom: 1.2rem;
  border-bottom: 1px solid var(--rg-ink);
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-filters ul {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-filters a {
  font-size: 1.3rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: opacity 0.18s ease;
}

.rg-filters a:hover {
  opacity: 0.5;
}

.rg-filters .is-current a {
  font-weight: 600;
}

/* --- Product grid --------------------------------------------------------- */

.rg-products {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4rem 3rem;
  margin: 0 0 4rem;
  padding: 0;
  list-style: none;
}

/* RG serve product tiles at 895x1023 — a portrait crop, not a square. */
.rg-product-card__media {
  background: var(--rg-tile);
  aspect-ratio: 895 / 1023;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.6rem;
  overflow: hidden;
}

.rg-products li:nth-child(3n + 2) .rg-product-card__media {
  background: var(--rg-tile-alt);
}

/* ILANEL's photography is in-situ interiors, not RG's cut-out product
   shots on white. `cover` fills the tile cleanly instead of leaving a
   landscape image floating in grey. Swap to `contain` with padding once
   the studio supplies cut-outs. */
.rg-product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease, opacity 0.3s ease;
}

.rg-product-card a:hover .rg-product-card__media img {
  transform: scale(1.03);
  opacity: 0.9;
}

.rg-product-card__title {
  margin: 0 0 0.3rem;
  font-size: 1.3rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-product-card__type {
  margin: 0 0 0.4rem;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price .woocommerce-Price-amount {
  font-weight: 300;
}

/* --- Discover More -------------------------------------------------------- */

.rg-discover {
  padding: 5rem 0 4rem;
}

.rg-discover__title {
  margin: 0 0 3.5rem;
  font-family: var(--rg-serif);
  font-size: 3.2rem;
  font-weight: 400;
  text-align: center;
}

/* RG centre the copy under discover cards. */
.rg-products--discover {
  margin-bottom: 3rem;
}

.rg-products--discover .rg-product-card__title,
.rg-products--discover .rg-product-card__type,
.rg-products--discover .rg-product-card__price {
  text-align: center;
}

.rg-discover__cta {
  margin: 0;
  text-align: center;
}

/* --- Share row ------------------------------------------------------------ */

.rg-share {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-share .rg-config__label {
  min-width: 11rem;
  margin: 0;
}

.rg-share a {
  font-size: 1.2rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease;
}

.rg-share a:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Lit / unlit toggle --------------------------------------------------- */

.rg-configure__preview {
  position: relative;
}

.rg-lightswitch {
  position: absolute;
  bottom: 1.6rem;
  left: 1.6rem;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.8rem 1.6rem;
  border: 1px solid rgba(0, 0, 0, 0.12);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(6px);
  font-size: 1rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.25s ease, border-color 0.25s ease;
}

.rg-lightswitch:hover {
  border-color: rgba(0, 0, 0, 0.35);
}

.rg-lightswitch__dot {
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 50%;
  background: #e8c37a;
  box-shadow: 0 0 0.7rem 0.15rem rgba(232, 195, 122, 0.9);
  transition: background 0.35s ease, box-shadow 0.35s ease;
}

/* Unlit: cool the image down and kill the glow. */
.rg-configure__preview.is-unlit img {
  filter: brightness(0.62) saturate(0.75) contrast(1.05);
}

.rg-configure__preview.is-unlit .rg-lightswitch__dot {
  background: #b9b9b9;
  box-shadow: none;
}

.rg-configure__preview img {
  transition: filter 0.6s ease;
}

/* --- 3D / 360° ------------------------------------------------------------ */

.rg-model {
  width: 100%;
  height: 100%;
  background: #fff;
  --poster-color: transparent;
}

/* --- Lightbox ------------------------------------------------------------- */

.rg-lightbox {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 4rem;
  background: rgba(12, 12, 12, 0.94);
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.3s ease, visibility 0.3s ease;
}

.rg-lightbox.is-open {
  opacity: 1;
  visibility: visible;
}

.rg-lightbox__img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  transform: scale(0.98);
  transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-lightbox.is-open .rg-lightbox__img {
  transform: none;
}

.rg-lightbox__close {
  position: absolute;
  top: 2rem;
  right: 2.5rem;
  width: 4rem;
  height: 4rem;
  border: 0;
  background: none;
  color: #fff;
  font-size: 3.2rem;
  line-height: 1;
  cursor: pointer;
  opacity: 0.7;
  transition: opacity 0.2s ease;
}

.rg-lightbox__close:hover {
  opacity: 1;
}

/* --- Reveal on scroll ----------------------------------------------------- */

.rg-reveal {
  opacity: 0;
  transform: translateY(1.8rem);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-reveal.is-visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .rg-reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* --- Header state --------------------------------------------------------- */

body.has-hero .rg-header {
  transition: background 0.35s ease, color 0.35s ease;
}

/* Once past the hero the header flips to dark-on-white and pins. */
body.has-hero.is-past-hero .rg-header {
  position: fixed;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(10px);
  color: var(--rg-ink);
  border-bottom: 1px solid var(--rg-rule);
}

body.has-hero.is-past-hero .rg-header::before {
  opacity: 0;
}

body.has-hero.is-past-hero .rg-navbtn span {
  background: var(--rg-ink);
}

/* --- Sticky enquiry bar --------------------------------------------------- */

.rg-stickybar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  padding: 1.4rem 0;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--rg-rule);
  transform: translateY(110%);
  transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-stickybar.is-visible {
  transform: none;
}

.rg-stickybar__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.rg-stickybar__meta {
  display: flex;
  align-items: baseline;
  gap: 1.6rem;
}

.rg-stickybar__name {
  font-size: 1.3rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-stickybar__price {
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-stickybar__actions {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.rg-btn--small {
  padding: 0.9rem 2.4rem;
}

.rg-btn--quiet {
  border-color: var(--rg-rule);
  color: var(--rg-muted);
}

.rg-btn--quiet:hover {
  border-color: var(--rg-ink);
  background: transparent;
  color: var(--rg-ink);
}

/* --- Footer --------------------------------------------------------------- */

.rg-footer {
  padding: 5rem 0 3rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-footer__inner {
  display: grid;
  gap: 4rem;
}

/* RG put the studio identity and address in a left-hand column BESIDE the
   nav columns, not stacked above them. */
.rg-footer__content {
  display: grid;
  grid-template-columns: 26rem minmax(0, 1fr);
  gap: 4rem 6rem;
  align-items: start;
}

.rg-footer__identity {
  display: grid;
  gap: 2.4rem;
  align-content: start;
}

.rg-footer__logo {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 2.4rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.rg-footer__address {
  display: grid;
  gap: 0.2rem;
  font-style: normal;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-footer__address a:hover {
  color: var(--rg-ink);
}

.rg-footer__spacer {
  margin-top: 1.2rem;
}

.rg-footer__navbar {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 3rem;
}

.rg-footer__navtitle {
  margin: 0 0 1.8rem;
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-footer__nav ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-footer__nav li {
  margin-bottom: 1rem;
}

.rg-footer__nav a {
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
  transition: color 0.2s ease;
}

.rg-footer__nav a:hover {
  color: var(--rg-ink);
}

.rg-footer__inline {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: 3rem;
  padding-top: 3rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-footer__acknowledgement {
  max-width: 62ch;
  margin: 0;
  font-size: 1.1rem;
  font-weight: 300;
  line-height: 1.6;
  color: var(--rg-muted);
}

.rg-footer__legal {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem 2rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-footer__legal a:hover {
  color: var(--rg-ink);
}

/* --- Homepage ------------------------------------------------------------- */

/* The homepage hero is the first thing anyone sees, so it runs taller than
   the product hero — but deliberately NOT the full viewport.
   At 92vh the products (the thing that actually converts) started entirely
   below the fold, and on a tall window the hero swallowed three quarters of
   the page. 78vh leaves the top of the product grid visible as an invitation
   to scroll, and the max-height stops tall desktop windows stretching it. */
.rg-hero--home {
  height: 78vh;
  max-height: 88rem;
  min-height: 52rem;
}

/* The overlay is a grid so the copy can sit on the lower third — RG place
   their hero text low-left, not centred. */
.rg-hero__overlay {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: grid;
  align-content: end;
  padding-bottom: 7.5rem;
  color: #fff;
  /* Photography is unpredictable; a scrim guarantees the copy stays legible
     without darkening the whole image. Weighted to the bottom third where the
     copy sits — a lighter wash left the standfirst looking washed out rather
     than deliberate. */
  /* Weighted to the bottom, where the copy sits, and eased out well before
     the top so the fixture keeps its contrast rather than being flattened. */
  background: linear-gradient(to top, rgba(0, 0, 0, 0.7), rgba(0, 0, 0, 0.26) 34%, rgba(0, 0, 0, 0) 66%);
  pointer-events: none;
}

/* Re-enable clicks only for the links inside the (non-interactive) overlay,
   so the scrim never eats a carousel arrow. */
.rg-hero__overlay a {
  pointer-events: auto;
}

/* Hero copy is centred, and that is a decision rather than a default.
   ILANEL's photography puts the fixture dead-centre with no usable negative
   space beside it at desktop widths. Left-aligned copy ran straight across
   the glass; narrowing it only pushed the lines toward the middle, because
   .rg-shell (max-width 168rem) is wider than a 1440px viewport and so has no
   slack for auto margins to take up. Centring sits the copy with the subject
   instead of fighting it. */
.rg-hero__copy {
  max-width: 66rem;
  margin: 0 auto;
  text-align: center;
}

.rg-hero__title {
  margin: 0 0 1.8rem;
  font-family: var(--rg-serif);
  font-size: 5.6rem;
  font-weight: 400;
  line-height: 1.06;
  letter-spacing: 0.01em;
  text-wrap: balance;
}

.rg-hero__standfirst {
  max-width: 48rem;
  margin: 0 auto;
  font-size: 2rem;
  font-weight: 300;
  line-height: 1.4;
  /* Near-white: at 0.88 over photography this read as washed out rather
     than as a deliberate secondary voice. */
  color: rgba(255, 255, 255, 0.96);
}

.rg-cta--hero {
  margin-top: 2.8rem;
}

.rg-link--light {
  color: #fff;
}

.rg-link--light:hover {
  border-bottom-color: #fff;
}

/* Dots sit above the deepest part of the scrim rather than in it. */
.rg-hero--home .rg-hero__dots {
  bottom: 3.5rem;
  z-index: 4;
}

.rg-main--home {
  padding-top: 1rem;
}

/* Vertical rhythm, moved toward RG's measured values.
   RG run 16.7rem top / 14.7rem bottom on desktop, collapsing to 10rem at
   ≤1023px and 5rem on mobile. We were at 5-7rem throughout, which is why the
   page read denser than theirs. These sit between the two: our headings are
   serif and larger than RG's 2.8rem sans, so they need less surrounding air
   to hold the page than RG's do. */
.rg-section--releases {
  padding-top: 11rem;
  padding-bottom: 2rem;
}

/* Four across on the homepage, against three on the range archive.
   The archive's 3-up left the fourth product stranded alone on a second row
   with two empty cells beside it — a hole in the middle of the page. The
   catalogue is currently four pieces, so 4-up fills exactly one row. */
.rg-section--releases .rg-products {
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 3.5rem 2.4rem;
  margin-bottom: 0;
}

/* At a quarter of the shell the archive's 895x1023 portrait crop turns into
   a narrow slot; a squarer tile keeps the fixture readable. */
.rg-section--releases .rg-product-card__media {
  aspect-ratio: 4 / 5;
}

/* Section headings across the homepage: the serif voice, one step down from
   the hero so the hierarchy stays obvious. */
/* RG put 9.8rem (98px) under every section h2. Ours are serif and larger, so
   the full value over-separates; 6.5rem keeps the generous feel without the
   heading floating away from what it introduces. */
.rg-section__heading {
  max-width: 30ch;
  margin: 0 0 6.5rem;
  font-family: var(--rg-serif);
  font-size: 3.6rem;
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: 0.01em;
}

/* Bottom padding is deliberately smaller than the top: it stacks with the
   provenance section's own top padding, and at 9rem the two summed to a
   visible hole between the About block and "Selected for". */
.rg-section--about {
  padding-top: 10rem;
  padding-bottom: 4rem;
}

/* On the homepage the About statement is the lede, so it runs larger than
   the utility .rg-section__title used on product pages. */
.rg-section__title--about {
  max-width: 100%;
  margin-bottom: 2.6rem;
  font-size: 2.6rem;
  line-height: 1.28;
}

.rg-facts {
  margin: 3rem 0 0;
  padding-top: 2.5rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-facts .rg-meta {
  margin-bottom: 1.2rem;
}

.rg-facts dd {
  margin: 0;
}

/* Provenance: names only, on a rule-separated row — the institutional
   credibility RG get from their "Tone" section. */
.rg-section--provenance {
  padding-top: 9rem;
  padding-bottom: 10rem;
}

.rg-provenance {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 2.5rem;
  margin: 0;
  padding-top: 3rem;
  border-top: 1px solid var(--rg-rule);
  list-style: none;
}

.rg-provenance__item {
  font-size: 1.5rem;
  font-weight: 300;
  line-height: 1.3;
  letter-spacing: 0.02em;
  color: #333;
}

/* Closing CTA on the flat tile grey, so the page ends on a defined block
   rather than trailing off into white. */
.rg-section--close {
  padding: 0 0 7rem;
}

.rg-close {
  padding: 6.5rem 6rem;
  background: var(--rg-tile-alt);
  text-align: center;
}

.rg-close__title {
  margin: 0 0 1.6rem;
  font-family: var(--rg-serif);
  font-size: 3.2rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-close__copy {
  max-width: 52rem;
  margin: 0 auto;
  font-size: 1.7rem;
  font-weight: 300;
  line-height: 1.4;
  color: #333;
}

/* --- Projects ------------------------------------------------------------- */

.rg-hero--project {
  height: 62vh;
  max-height: 72rem;
  min-height: 40rem;
}

.rg-main--project {
  padding-bottom: 4rem;
}

.rg-section--featured {
  padding-top: 5rem;
  padding-bottom: 6rem;
}

.rg-section--used {
  padding-top: 6rem;
  padding-bottom: 6rem;
}

/* Project cards: wider crop than product tiles. These are interiors, not
   objects on a plinth — a portrait crop cuts the room out of the frame. */
.rg-projects {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 3rem 2.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-project-card__media {
  aspect-ratio: 3 / 2;
  margin-bottom: 1.6rem;
  background: var(--rg-tile);
  overflow: hidden;
}

.rg-project-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease;
}

.rg-project-card a:hover .rg-project-card__media img {
  transform: scale(1.03);
}

.rg-project-card__title {
  margin: 0 0 0.4rem;
  font-size: 1.3rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-project-card__cta {
  margin: 0;
  font-size: 1.1rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-project-card a:hover .rg-project-card__cta {
  color: var(--rg-ink);
}

/* Products shown on a project page. Two-up: a project usually features one
   or two pieces, and three narrow columns would leave a hole. */
.rg-products--used {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  max-width: 96rem;
}

.rg-project-gallery {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 2.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-project-gallery img {
  width: 100%;
  aspect-ratio: 3 / 2;
  object-fit: cover;
  background: var(--rg-tile);
}

/* --- Responsive ----------------------------------------------------------- */

@media (max-width: 1100px) {
  .rg-article__row,
  .rg-article--reversed .rg-article__row {
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  /* Keep the image below the copy on reversed rows when stacked. */
  .rg-article--reversed .rg-article__col--media {
    order: 2;
  }

  .rg-configure__inner {
    grid-template-columns: 1fr;
    gap: 4rem;
  }

  .rg-hero {
    height: 70vh;
  }

  .rg-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rg-product__name {
    font-size: 4.4rem;
  }

  .rg-hero--home {
    height: 72vh;
  }

  .rg-hero__title {
    font-size: 4.4rem;
  }

  .rg-section__heading {
    font-size: 3rem;
  }

  /* Five across becomes unreadable well before the layout breaks. */
  .rg-provenance {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 2rem;
  }

  /* Needs the same specificity as the 4-up rule above to win. */
  .rg-section--releases .rg-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rg-projects {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .rg-footer__content,
  .rg-footer__inline {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .rg-footer__navbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2.5rem;
  }

  .rg-footer__legal {
    justify-content: flex-start;
  }

  .rg-stickybar__inner {
    gap: 1rem;
  }

  .rg-stickybar__meta {
    flex-direction: column;
    gap: 0.2rem;
  }
}

@media (max-width: 760px) {
  .rg-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .rg-section__list {
    columns: 1;
  }

  .rg-hero {
    height: 52vh;
    min-height: 30rem;
  }

  .rg-header__logo {
    font-size: 2.2rem;
  }

  /* The homepage hero keeps more height than the product hero — it carries
     the h1 and standfirst, which need room. */
  .rg-hero--home {
    height: 68vh;
    min-height: 42rem;
  }

  .rg-hero__overlay {
    padding-bottom: 7rem;
  }

  .rg-hero__title {
    font-size: 3.4rem;
    max-width: 100%;
  }

  .rg-hero__standfirst {
    font-size: 1.6rem;
    max-width: 100%;
  }

  /* The arrows sit mid-height and collide with the headline on a narrow
     canvas. The dots and auto-advance still drive the carousel, and swipe is
     the expected gesture here anyway. */
  .rg-hero--home .rg-hero__nav {
    display: none;
  }

  .rg-section__heading {
    font-size: 2.6rem;
    margin-bottom: 3rem;
  }

  /* RG collapse their 16.7rem desktop rhythm to 5rem on mobile; the generous
     desktop spacing above would otherwise be dead scrolling on a phone. */
  .rg-section--releases,
  .rg-section--about,
  .rg-section--provenance {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .rg-section__title--about {
    font-size: 2.1rem;
  }

  .rg-provenance {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rg-close {
    padding: 4.5rem 2.5rem;
  }

  .rg-close__title {
    font-size: 2.6rem;
  }
}

@media (max-width: 374px) {
  :root {
    --rg-shell: 2rem;
  }

  .rg-products {
    grid-template-columns: 1fr;
  }

  .rg-section--releases .rg-products {
    grid-template-columns: 1fr;
  }

  .rg-projects,
  .rg-products--used,
  .rg-project-gallery {
    grid-template-columns: 1fr;
  }
}

/**
 * Hero carousel + configurator.
 *
 * Vanilla, no dependencies — the Playground sandbox blocks external
 * scripts and the behaviour is simple enough not to need a library.
 */
(function () {
  'use strict';

  /* --- Hero carousel: cross-fade, matching RG's .slider--fade --------- */

  function initHero() {
    var hero = document.querySelector('.js-hero');
    if (!hero) return;

    var slides = hero.querySelectorAll('.rg-hero__slide');
    if (slides.length < 2) return;

    var dots = hero.querySelectorAll('.rg-hero__dot');
    var index = 0;
    var timer = null;

    function show(next) {
      index = (next + slides.length) % slides.length;

      slides.forEach(function (slide, i) {
        slide.classList.toggle('is-active', i === index);
      });

      dots.forEach(function (dot, i) {
        dot.classList.toggle('is-active', i === index);
      });
    }

    function advance() {
      show(index + 1);
    }

    function restart() {
      window.clearInterval(timer);
      timer = window.setInterval(advance, 6000);
    }

    hero.querySelector('.js-hero-next').addEventListener('click', function () {
      show(index + 1);
      restart();
    });

    hero.querySelector('.js-hero-prev').addEventListener('click', function () {
      show(index - 1);
      restart();
    });

    dots.forEach(function (dot) {
      dot.addEventListener('click', function () {
        show(parseInt(dot.dataset.index, 10));
        restart();
      });
    });

    /* Keyboard: arrows step the carousel when it is in view. */
    document.addEventListener('keydown', function (e) {
      if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
      var box = hero.getBoundingClientRect();
      if (box.bottom < 0 || box.top > window.innerHeight) return;
      show(index + (e.key === 'ArrowRight' ? 1 : -1));
      restart();
    });

    /* Swipe on touch devices. */
    var startX = null;

    hero.addEventListener(
      'touchstart',
      function (e) {
        startX = e.touches[0].clientX;
      },
      { passive: true }
    );

    hero.addEventListener(
      'touchend',
      function (e) {
        if (startX === null) return;
        var dx = e.changedTouches[0].clientX - startX;
        if (Math.abs(dx) > 45) {
          show(index + (dx < 0 ? 1 : -1));
          restart();
        }
        startX = null;
      },
      { passive: true }
    );

    /* Pause the auto-advance while the pointer rests on the hero — nothing
     * is more irritating than an image changing while you study it. */
    hero.addEventListener('mouseenter', function () {
      window.clearInterval(timer);
    });

    hero.addEventListener('mouseleave', restart);

    restart();
  }

  /* --- Lightbox --------------------------------------------------------
   * Click a story image or the configurator preview to inspect it full
   * screen. These are hand-finished pieces; buyers want to see the join,
   * the glass, the finish up close.
   *
   * The hero is deliberately excluded — it is a carousel, and a zoom
   * cursor over it competes with the slide controls.
   */

  function initLightbox() {
    var storyImgs = document.querySelectorAll('.rg-feature img, .rg-configure__preview img');

    if (!storyImgs.length) return;

    var box = document.createElement('div');
    box.className = 'rg-lightbox';
    box.setAttribute('role', 'dialog');
    box.setAttribute('aria-modal', 'true');
    box.setAttribute('aria-label', 'Image viewer');
    box.innerHTML =
      '<button class="rg-lightbox__close" type="button" aria-label="Close">&times;</button>' +
      '<img class="rg-lightbox__img" alt="">';
    document.body.appendChild(box);

    var img = box.querySelector('.rg-lightbox__img');
    var lastFocus = null;

    function open(src) {
      img.src = src;
      box.classList.add('is-open');
      document.body.style.overflow = 'hidden';
      lastFocus = document.activeElement;
      box.querySelector('.rg-lightbox__close').focus();
    }

    function close() {
      box.classList.remove('is-open');
      document.body.style.overflow = '';
      if (lastFocus) lastFocus.focus();
    }

    box.addEventListener('click', function (e) {
      if (e.target === box || e.target.closest('.rg-lightbox__close')) close();
    });

    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && box.classList.contains('is-open')) close();
    });

    storyImgs.forEach(function (el) {
      el.style.cursor = 'zoom-in';
      el.addEventListener('click', function () {
        open(el.currentSrc || el.src);
      });
    });
  }

  /* --- Configurator: swap preview, update summary and price ----------- */
  /* --- Configurator ----------------------------------------------------
   * Drives real WooCommerce variations. Every price, image and stock state
   * comes from Woo; nothing here is invented.
   *
   * Three things this does that a naive variation picker does not:
   *
   *   1. Options that cannot be reached from the current selection are
   *      disabled *before* you click them, so you never land on a dead
   *      combination and have to back out.
   *   2. The price cross-fades between values instead of snapping, and
   *      counts to the new figure — a change you can follow.
   *   3. Selection state is announced to screen readers and persisted
   *      between visits.
   */

  function initConfigurator() {
    var form = document.querySelector('.rg-config');
    if (!form) return;

    var preview = document.querySelector('.js-config-image');
    var summary = form.querySelector('.js-config-summary');
    var priceEl = form.querySelector('.js-config-price');
    var unavailableEl = form.querySelector('.js-config-unavailable');

    var variations = [];
    try {
      variations = JSON.parse(form.dataset.variations || '[]');
    } catch (e) {
      variations = [];
    }

    // Axis keys, in the order the fieldsets appear.
    var axes = Array.prototype.map.call(
      form.querySelectorAll('.rg-config__group[data-axis]'),
      function (g) {
        return g.dataset.axis;
      }
    );

    if (!axes.length) return;

    function inputsFor(axis) {
      return form.querySelectorAll('input[name="attribute_' + axis + '"]');
    }

    function selected() {
      var out = {};
      axes.forEach(function (axis) {
        var checked = form.querySelector('input[name="attribute_' + axis + '"]:checked');
        out[axis] = checked ? checked.value : null;
      });
      return out;
    }

    /* A variation matches when every axis either agrees or is unconstrained
     * ("any" — Woo leaves the attribute blank when it applies to all). */
    function matches(variation, choice, ignoreAxis) {
      return axes.every(function (axis) {
        if (axis === ignoreAxis) return true;
        var want = choice[axis];
        if (!want) return true;
        var have = variation.attributes['attribute_' + axis];
        return !have || have === want;
      });
    }

    function findVariation(choice) {
      for (var i = 0; i < variations.length; i++) {
        if (matches(variations[i], choice, null)) return variations[i];
      }
      return null;
    }

    /* --- Reachability ---------------------------------------------------
     * For each option, ask: if I picked this, would any variation exist?
     * If not, dim and disable it. This is the difference between a picker
     * that guides you and one that lets you walk into a wall.
     */
    function updateReachability(choice) {
      if (!variations.length) return;

      axes.forEach(function (axis) {
        Array.prototype.forEach.call(inputsFor(axis), function (input) {
          var hypothetical = Object.assign({}, choice);
          hypothetical[axis] = input.value;

          var reachable = variations.some(function (v) {
            return matches(v, hypothetical, null);
          });

          input.disabled = !reachable;
          var label = input.closest('label');
          if (label) label.classList.toggle('is-unavailable', !reachable);
        });
      });
    }

    /* --- Price animation ------------------------------------------------
     * Counts from the old figure to the new one over ~420ms. Digits are
     * rewritten in place, so the currency symbol and any "from" wording
     * from Woo's price_html survive untouched.
     */
    var priceAnim = null;

    function animatePrice(html, from, to) {
      if (priceAnim) window.cancelAnimationFrame(priceAnim);

      var reduced =
        window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      if (reduced || !from || !to || from === to) {
        priceEl.innerHTML = html;
        return;
      }

      var start = performance.now();
      var DURATION = 420;

      // Rewrite the first number in the markup, preserving everything else.
      var numberPattern = /([\d][\d,]*\.?\d*)/;

      function frame(now) {
        var t = Math.min(1, (now - start) / DURATION);
        // easeOutCubic — fast then settling, matching the page's motion.
        var eased = 1 - Math.pow(1 - t, 3);
        var value = from + (to - from) * eased;

        priceEl.innerHTML = html.replace(
          numberPattern,
          value.toLocaleString(undefined, {
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
          })
        );

        if (t < 1) priceAnim = window.requestAnimationFrame(frame);
      }

      priceAnim = window.requestAnimationFrame(frame);
    }

    /* --- Preview image --------------------------------------------------
     * Cross-fades rather than swapping, and preloads before showing so the
     * panel never flashes an empty frame.
     */
    function setPreview(src) {
      if (!preview || !src || preview.src === src) return;

      var next = new Image();
      next.onload = function () {
        preview.style.opacity = '0';
        window.setTimeout(function () {
          preview.src = src;
          preview.style.opacity = '';
        }, 180);
      };
      next.src = src;
    }

    /* --- Scale drawing --------------------------------------------------- */
    var scaleFixture = document.querySelector('.js-scale-fixture');
    var scaleCaption = document.querySelector('.js-scale-caption');
    var TABLE_MM = 2400;

    function updateScale() {
      if (!scaleFixture) return;

      var sized = form.querySelector('input[data-mm]:checked');
      if (!sized) return;

      var mm = parseInt(sized.dataset.mm || '0', 10);
      if (!mm) return;

      // The table is drawn at 78% of the stage; scale the fixture to match.
      scaleFixture.style.width = (mm / TABLE_MM) * 78 + '%';
      if (scaleCaption) scaleCaption.textContent = mm + ' mm';
    }

    /* --- Persistence -----------------------------------------------------
     * People compare lighting for weeks. Losing the selection on every
     * return visit is needless drop-off.
     */
    var KEY = 'ilanel-config-' + (document.body.className.match(/postid-(\d+)/) || [, 'x'])[1];

    function save() {
      try {
        window.localStorage.setItem(KEY, JSON.stringify(selected()));
      } catch (e) {
        /* Private mode or quota. Not fatal. */
      }
    }

    function restore() {
      var saved;
      try {
        saved = JSON.parse(window.localStorage.getItem(KEY) || 'null');
      } catch (e) {
        return false;
      }
      if (!saved || !window.CSS || !window.CSS.escape) return false;

      var restored = false;
      axes.forEach(function (axis) {
        if (!saved[axis]) return;
        var input = form.querySelector(
          'input[name="attribute_' + axis + '"][value="' + window.CSS.escape(saved[axis]) + '"]'
        );
        if (input && !input.checked) {
          input.checked = true;
          restored = true;
        }
      });
      return restored;
    }

    /* --- Main update ----------------------------------------------------- */
    var lastPrice = null;

    function update() {
      var choice = selected();

      updateReachability(choice);

      var variation = findVariation(choice);

      // Human-readable selection, e.g. "1800mm · Brushed Brass · Smoke".
      var parts = axes
        .map(function (axis) {
          return choice[axis];
        })
        .filter(Boolean);
      if (summary) summary.textContent = parts.join(' · ');

      if (variation) {
        if (unavailableEl) unavailableEl.hidden = true;
        form.classList.remove('is-unavailable');

        if (priceEl && variation.price_html) {
          animatePrice(variation.price_html, lastPrice, variation.display);
          lastPrice = variation.display;
        }

        setPreview(variation.image);
      } else if (variations.length) {
        // Reachability should prevent this, but a restored selection from an
        // older catalogue can land here. Say so plainly rather than showing
        // a stale price.
        if (unavailableEl) unavailableEl.hidden = false;
        form.classList.add('is-unavailable');
      }

      updateScale();
    }

    form.addEventListener('change', function () {
      update();
      save();
    });

    if (restore()) {
      var note = form.querySelector('.js-config-restored');
      if (note) note.hidden = false;
    }

    update();
  }

  /* --- Lit / unlit toggle -------------------------------------------- */

  function initLightSwitch() {
    var btn = document.querySelector('.js-lightswitch');
    var preview = document.querySelector('.rg-configure__preview');
    if (!btn || !preview) return;

    var label = btn.querySelector('.rg-lightswitch__text');
    var lit = true;

    btn.addEventListener('click', function () {
      lit = !lit;
      preview.classList.toggle('is-unlit', !lit);
      btn.setAttribute('aria-pressed', String(lit));
      if (label) label.textContent = lit ? 'Lit' : 'Unlit';
    });
  }

  /* --- Reveal on scroll ------------------------------------------------
   * Sections fade and rise slightly as they enter the viewport. Kept
   * subtle — a few hundred ms, small travel. Respects
   * prefers-reduced-motion by simply not running.
   */

  function initReveal() {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    if (!('IntersectionObserver' in window)) return;

    var targets = document.querySelectorAll(
      '.rg-article__col, .rg-feature, .rg-section, .rg-product-card, .rg-configure__panel, .rg-configure__preview'
    );

    targets.forEach(function (el) {
      el.classList.add('rg-reveal');
    });

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (!entry.isIntersecting) return;
          entry.target.classList.add('is-visible');
          io.unobserve(entry.target);
        });
      },
      { rootMargin: '0px 0px -10% 0px', threshold: 0.08 }
    );

    targets.forEach(function (el) {
      io.observe(el);
    });
  }

  /* --- Sticky enquiry bar ----------------------------------------------
   * Appears once the configurator scrolls out of view, so the call to
   * action is never more than a tap away on a long page.
   */

  function initStickyBar() {
    var config = document.getElementById('configure');
    var bar = document.querySelector('.js-stickybar');
    if (!config || !bar) return;

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          // Show only once the configurator has been scrolled past.
          var past = !entry.isIntersecting && entry.boundingClientRect.top < 0;
          bar.classList.toggle('is-visible', past);
        });
      },
      { threshold: 0 }
    );

    io.observe(config);
  }

  /* --- Header state on scroll ------------------------------------------
   * Over the hero the header is white on photography; once past it, it
   * needs to flip to dark on white.
   */

  function initHeaderState() {
    var hero = document.querySelector('.rg-hero');
    if (!hero || !document.body.classList.contains('has-hero')) return;

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          document.body.classList.toggle('is-past-hero', !entry.isIntersecting);
        });
      },
      { threshold: 0, rootMargin: '-80px 0px 0px 0px' }
    );

    io.observe(hero);
  }

  function init() {
    initHero();
    initConfigurator();
    initLightSwitch();
    initLightbox();
    initReveal();
    initStickyBar();
    initHeaderState();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/**
 * Soft page transitions.
 *
 * Loaded on every page, not just products. Two halves:
 *
 *   1. Fade the page in on load, so arriving never flashes.
 *   2. Intercept same-origin link clicks, fade out, then navigate. The
 *      browser paints the next page during the fade, so the seam between
 *      pages disappears.
 *
 * Deliberately not a SPA router — no history rewriting, no fetch, no
 * state to get out of sync. Just a cross-fade over a real navigation, so
 * the back button, refresh and deep links all behave normally.
 *
 * Falls back to plain navigation if anything is unsupported, and no-ops
 * entirely under prefers-reduced-motion.
 */
(function () {
  'use strict';

  var DURATION = 320;

  var reduced =
    window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* --- Fade in ------------------------------------------------------- */

  function revealPage() {
    document.documentElement.classList.add('is-ready');
  }

  if (reduced) {
    revealPage();
  } else {
    // rAF so the initial painted frame is the faded-out state, otherwise
    // the browser can skip straight to opaque and the fade is lost.
    window.requestAnimationFrame(function () {
      window.requestAnimationFrame(revealPage);
    });
  }

  /* --- Fade out before navigating ------------------------------------ */

  if (reduced) return;

  function isInternalNavigation(link, event) {
    if (event.defaultPrevented) return false;
    if (event.button !== 0) return false;
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return false;

    if (!link || !link.href) return false;
    if (link.target && link.target !== '_self') return false;
    if (link.hasAttribute('download')) return false;
    if (link.getAttribute('rel') === 'external') return false;

    var url;
    try {
      url = new URL(link.href, window.location.href);
    } catch (e) {
      return false;
    }

    if (url.origin !== window.location.origin) return false;

    // In-page anchors scroll; they must not trigger a page fade.
    if (url.pathname === window.location.pathname && url.hash) return false;

    // Leave non-http schemes (mailto:, tel:) alone.
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return false;

    return url.href;
  }

  document.addEventListener('click', function (event) {
    var link = event.target.closest && event.target.closest('a');
    if (!link) return;

    var href = isInternalNavigation(link, event);
    if (!href) return;

    event.preventDefault();

    document.documentElement.classList.add('is-leaving');

    // Navigate once the fade has played. The timeout is the guarantee —
    // transitionend can be missed if the element is removed or the tab
    // is backgrounded.
    window.setTimeout(function () {
      window.location.href = href;
    }, DURATION);
  });

  /* Restoring from bfcache shows the faded-out state, so clear it. */
  window.addEventListener('pageshow', function (event) {
    if (event.persisted) {
      document.documentElement.classList.remove('is-leaving');
      revealPage();
    }
  });
})();
